59	 */
60	export function BatchList({
61	  produtoId,
62	  storeId,
63	  produtoNome,
64	  diasValidadePadrao,
65	  onUpdate,
66	}: BatchListProps) {
67	  const [batches, setBatches] = useState<StockBatch[]>([]);
68	  const [loading, setLoading] = useState(false);
69	  const pendingUpdates = React.useRef<Record<string, number>>({});
70	  const updateTimeouts = React.useRef<Record<string, number>>({});
71	
72	  // New Batch Form
73	  const [newFabricacao, setNewFabricacao] = useState<Date | undefined>(
74	    new Date(),
75	  );
76	  const [newValidade, setNewValidade] = useState<Date | undefined>(
77	    diasValidadePadrao ? addDays(new Date(), diasValidadePadrao) : undefined,
78	  );
79	  const [newQtd, setNewQtd] = useState('');
80	  const [isAdding, setIsAdding] = useState(false);
81	
82	  const { toast } = useToast();
83	
84	  useEffect(() => {
85	    fetchBatches();
86	    // eslint-disable-next-line react-hooks/exhaustive-deps
87	  }, [produtoId, storeId]);
88	
89	  useEffect(() => {
90	    if (newFabricacao && diasValidadePadrao) {
91	      setNewValidade(addDays(newFabricacao, diasValidadePadrao));
92	    }
93	  }, [newFabricacao, diasValidadePadrao]);
94	
95	  const fetchBatches = async () => {
96	    setLoading(true);
97	    try {
98	      const { data, error } = await supabase
99	        .from('estoque_lotes' as any)
100	        .select(
101	          `
102	                    id,
103	                    lote_id,
104	                    quantidade,
105	                    lotes (
106	                        id,
107	                        codigo,
108	                        data_validade,
109	                        data_fabricacao
110	                    )
111	                `,
112	        )
113	        .eq('produto_id', produtoId)
114	        .eq('loja_id', storeId);
115	
116	      if (error) throw error;
117	
118	      // Caixa vazia (qtd 0) "some" da tela — saldo zerado não é caixa.
119	      const visiveis = ((data || []) as any[]).filter(
120	        (r) => Number(r.quantidade) > 0,
121	      );
122	      const sorted = visiveis.sort((a, b) => {
123	        const dateA = new Date(a.lotes.data_validade).getTime();
124	        const dateB = new Date(b.lotes.data_validade).getTime();
125	        return dateA - dateB;
126	      });
127	
128	      setBatches(sorted);
129	    } catch (error) {
130	      console.error('Error fetching batches:', error);
131	    } finally {
132	      setLoading(false);
133	    }
134	  };
135	
136	  const handleAddBatch = async () => {
137	    if (!newFabricacao || !newValidade || !newQtd) {
138	      toast({ title: 'Preencha todos os campos', variant: 'destructive' });
139	      return;
140	    }
141	
142	    const fabricacaoStr = format(newFabricacao, 'ddMMyyyy');
143	    // Código padrão 9 chars (L+ddMMyyyy) — sem HHmm, pra não divergir do mesmo lote físico.
144	    const generatedLoteCode = `L${fabricacaoStr}`;
145	
146	    try {
147	      // Criação idempotente: reaproveita o lote existente em vez de criar id divergente.
148	      const { data: loteId, error: loteError } = await (supabase.rpc as any)('find_or_create_lote', {
149	        p_produto_id: produtoId,
150	        p_codigo: generatedLoteCode,
151	        p_data_validade: format(newValidade, 'yyyy-MM-dd'),
152	        p_data_fabricacao: format(newFabricacao, 'yyyy-MM-dd'),
153	        p_loja_id: storeId,
154	        p_atualizar_datas: true, // seletor é a verdade: corrige datas ao reusar lote do dia (ADR-20260619)
155	      });
156	
157	      if (loteError) throw loteError;
158	
159	      const { error: stockError } = await supabase
160	        .from('estoque_lotes' as any)
161	        .insert({
162	          loja_id: storeId,
163	          produto_id: produtoId,
164	          lote_id: loteId,
165	          quantidade: parseFloat(newQtd),
166	        });
167	
168	      if (stockError) throw stockError;
