179	      console.error(e);
180	      toast({
181	        title: 'Erro ao criar lote',
182	        description: e.message || 'Verifique os dados e tente novamente',
183	        variant: 'destructive',
184	      });
185	    }
186	  };
187	
188	  // Tudo flui por uma RPC atômica: nada de UPDATE direto em estoque_lotes
189	  // (que disparava o reconciliador 'sync_lote_auto' fantasma). A RPC insere a
190	  // movimentação e os triggers sincronizam estoque + estoque_lotes coerentes.
191	  const processBatchUpdate = async (
192	    stockBatchId: string,
193	    deltaTotal: number,
194	    loteId: string,
195	  ) => {
196	    try {
197	      if (deltaTotal !== 0) {
198	        const { data, error } = await (supabase.rpc as any)(
199	          'ajustar_lote_contagem',
200	          {
201	            p_lote_id: loteId,
