236	    const newQ = Math.max(0, currentQtd + delta);
237	    const effectiveDelta = newQ - currentQtd;
238	
239	    if (effectiveDelta === 0) return;
240	
241	    setBatches((prev) =>
242	      prev.map((b) => (b.id === stockBatchId ? { ...b, quantidade: newQ } : b)),
243	    );
244	
245	    if (updateTimeouts.current[stockBatchId]) {
