275	        color: 'text-orange-600 bg-orange-50 border-orange-200',
276	        label: 'Vence em breve',
277	        icon: AlertTriangle,
278	      };
279	    return {
280	      color: 'text-green-600 bg-green-50 border-green-200',
281	      label: 'Ok',
282	      icon: Calendar,
283	    };
284	  };
285	
286	  return (
