315	                  {newFabricacao
316	                    ? format(newFabricacao, 'dd/MM/yyyy')
317	                    : 'Fabricação'}
318	                </Button>
319	              </PopoverTrigger>
320	              <PopoverContent className="w-auto p-0">
321	                <CalendarComponent
