323	                  selected={newFabricacao}
324	                  onSelect={setNewFabricacao}
325	                  initialFocus
326	                />
327	              </PopoverContent>
328	            </Popover>
329	            <Popover>
330	              <PopoverTrigger asChild>
331	                <Button
332	                  variant="outline"
333	                  className={cn(
334	                    'h-8 text-xs justify-start text-left font-normal',
335	                    !newValidade && 'text-muted-foreground',
