340	                </Button>
341	              </PopoverTrigger>
342	              <PopoverContent className="w-auto p-0">
343	                <CalendarComponent
344	                  mode="single"
345	                  selected={newValidade}
346	                  onSelect={setNewValidade}
347	                  initialFocus
348	                />
349	              </PopoverContent>
350	            </Popover>
351	            <Input data-mia-field="new_qtd"
