356	              className="h-8 text-xs"
357	            />
358	          </div>
359	          <Button data-mia-action="add-batch"
360	            size="sm"
361	            onClick={handleAddBatch}
362	            className="w-full h-7 bg-[#57715B] text-white hover:bg-[#57715B]/90 text-xs"
363	          >
