369	      <div className="space-y-2">
370	        {batches.length === 0 ? (
371	          <div className="text-center py-4 text-xs text-muted-foreground bg-black/5 rounded-lg border border-dashed border-black/10">
372	            Nenhum lote neste estoque.
373	          </div>
