390	                      className={cn(
391	                        'text-[10px] h-5 px-1.5 gap-1',
392	                        status.color,
393	                      )}
394	                    >
395	                      <StatusIcon className="w-3 h-3" />
396	                      Val:{' '}
397	                      {format(
398	                        parseISO(batch.lotes.data_validade),
399	                        'dd/MM/yyyy',
400	                      )}
401	                    </Badge>
402	                    {batch.lotes.data_fabricacao && (
403	                      <Badge
404	                        variant="outline"
405	                        className="text-[10px] h-5 px-1.5 gap-1 text-gray-500 border-gray-200"
406	                      >
407	                        Fab:{' '}
408	                        {format(
409	                          parseISO(batch.lotes.data_fabricacao),
410	                          'dd/MM/yyyy',
411	                        )}
412	                      </Badge>
413	                    )}
414	                  </div>
415	                  <div className="text-[10px] text-muted-foreground uppercase tracking-wider font-bold">
416	                    {status.label}
417	                  </div>
418	                </div>
419	
420	                <div className="flex items-center gap-3">
421	                  <div className="flex items-center gap-1 bg-white dark:bg-black rounded-lg border border-gray-200 dark:border-gray-800 p-0.5">
422	                    <Button
423	                      variant="ghost"
424	                      size="icon"
425	                      className="h-7 w-7 rounded-md hover:bg-gray-100 dark:hover:bg-gray-800"
426	                      onClick={() =>
427	                        adjustQuantity(
428	                          batch.id,
429	                          batch.quantidade,
430	                          -1,
431	                          batch.lote_id,
432	                        )
433	                      }
434	                    >
435	                      <Minus className="w-3 h-3" />
436	                    </Button>
437	                    <span className="w-12 text-center font-mono font-bold text-sm">
438	                      {batch.quantidade}
439	                    </span>
440	                    <Button
441	                      variant="ghost"
442	                      size="icon"
443	                      className="h-7 w-7 rounded-md hover:bg-gray-100 dark:hover:bg-gray-800"
444	                      onClick={() =>
445	                        adjustQuantity(
446	                          batch.id,
447	                          batch.quantidade,
448	                          +1,
449	                          batch.lote_id,
450	                        )
451	                      }
452	                    >
453	                      <Plus className="w-3 h-3" />
454	                    </Button>
455	                  </div>
456	                </div>
457	              </div>
458	            );
459	          })
460	        )}
461	      </div>
462	    </div>
463	  );
464	}
