-- Fix em bipar_etiqueta: no backfill, se o lote_uuid do payload nao existe em lotes,
-- resolve por codigo+validade via find_or_create_lote ou usa NULL.
-- Antes: INSERT com UUID morto -> FK rejeitava -> movimentacoes FK cascateava erro.
CREATE OR REPLACE FUNCTION public.bipar_etiqueta(p_uid text, p_etapa text, p_contexto jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public'
AS $function$
DECLARE
  v_etiqueta public.etiquetas_qr%ROWTYPE;
  v_user_id uuid := auth.uid();
  v_user_nome text; v_status_anterior text; v_status_novo text; v_loja_id integer;
  v_alertas jsonb := '[]'::jsonb; v_referencia_tipo text; v_referencia_id text;
  v_payload jsonb; v_pid_text text; v_pid_int integer; v_lote_uuid uuid;
  v_produto_nome text; v_lote_codigo text; v_lote_validade date; v_qty_interna numeric;
BEGIN
  IF p_etapa NOT IN ('separacao','conferencia','entrada','saida','consumo','descarte') THEN
    RETURN jsonb_build_object('ok', false, 'erro', 'Etapa invalida: ' || p_etapa); END IF;
  SELECT COALESCE(raw_user_meta_data->>'nome', email) INTO v_user_nome FROM auth.users WHERE id = v_user_id;
  v_loja_id := NULLIF(p_contexto->>'loja_id','')::integer;
  v_referencia_tipo := p_contexto->>'referencia_tipo'; v_referencia_id := p_contexto->>'referencia_id';
  v_payload := p_contexto->'payload';
  SELECT * INTO v_etiqueta FROM public.etiquetas_qr WHERE uid = p_uid;
  IF NOT FOUND THEN
    IF v_payload IS NULL THEN RETURN jsonb_build_object('ok', false, 'erro', 'Etiqueta nao cadastrada e sem payload para backfill'); END IF;
    v_pid_text := COALESCE(v_payload->>'pid', v_payload->>'p');
    IF v_pid_text IS NULL OR v_pid_text = '' THEN RETURN jsonb_build_object('ok', false, 'erro', 'Etiqueta nao cadastrada e payload sem produto'); END IF;
    v_pid_int := v_pid_text::integer;
    v_lote_uuid := NULLIF(COALESCE(v_payload->>'lid', v_payload->>'l'),'')::uuid;
    v_qty_interna := COALESCE(NULLIF(COALESCE(v_payload->>'qty', v_payload->>'q'),'')::numeric, 1);
    SELECT nome INTO v_produto_nome FROM public.produtos_master WHERE id = v_pid_int;
    -- Resolve lote_id seguro: UUID morto -> tenta por codigo+validade -> NULL
    IF v_lote_uuid IS NOT NULL THEN
      SELECT codigo, data_validade INTO v_lote_codigo, v_lote_validade FROM public.lotes WHERE id = v_lote_uuid;
      IF NOT FOUND THEN
        v_lote_codigo  := NULLIF(COALESCE(v_payload->>'lote', v_payload->>'lc'), '');
        v_lote_validade := NULLIF(COALESCE(v_payload->>'val', v_payload->>'v'), '')::date;
        IF v_lote_codigo IS NOT NULL AND v_lote_validade IS NOT NULL THEN
          v_lote_uuid := public.find_or_create_lote(v_pid_int, v_lote_codigo, v_lote_validade, NULL, NULL);
        ELSE v_lote_uuid := NULL; END IF;
      END IF;
    END IF;
    INSERT INTO public.etiquetas_qr (uid, produto_master_id, lote_id, embalagem_nome, quantidade_interna, quantidade_disponivel, consumida_inteira, produto_nome_snapshot, lote_codigo_snapshot, lote_validade_snapshot, loja_origem_id, loja_atual_id, status, tipo_embalagem, foi_separada, separada_at, separada_por, foi_conferida, conferida_at, conferida_por, backfilled, qr_payload)
    VALUES (p_uid, v_pid_int, v_lote_uuid, COALESCE(v_payload->>'emb', v_payload->>'n'), v_qty_interna, v_qty_interna, false, v_produto_nome, v_lote_codigo, v_lote_validade, NULL, v_loja_id, CASE p_etapa WHEN 'separacao' THEN 'gerada' WHEN 'conferencia' THEN 'gerada' WHEN 'entrada' THEN 'recebida' WHEN 'saida' THEN 'em_transito' WHEN 'consumo' THEN 'consumida' WHEN 'descarte' THEN 'descartada' END, COALESCE(v_payload->>'tipo', v_payload->>'t', 'caixa'), (p_etapa = 'separacao'), CASE WHEN p_etapa = 'separacao' THEN NOW() ELSE NULL END, CASE WHEN p_etapa = 'separacao' THEN v_user_id ELSE NULL END, (p_etapa = 'conferencia'), CASE WHEN p_etapa = 'conferencia' THEN NOW() ELSE NULL END, CASE WHEN p_etapa = 'conferencia' THEN v_user_id ELSE NULL END, true, v_payload) RETURNING * INTO v_etiqueta;
    v_alertas := v_alertas || jsonb_build_array('Etiqueta antiga registrada retroativamente (backfill)');
    INSERT INTO public.etiquetas_qr_eventos (etiqueta_uid, tipo_evento, etapa, status_anterior, status_novo, loja_id, usuario_id, usuario_nome, referencia_tipo, referencia_id, metadata) VALUES (p_uid, 'backfilled', 'backfill', NULL, v_etiqueta.status, v_loja_id, v_user_id, v_user_nome, v_referencia_tipo, v_referencia_id, jsonb_build_object('etapa_origem', p_etapa, 'payload', v_payload));
    RETURN jsonb_build_object('ok', true, 'etiqueta', to_jsonb(v_etiqueta), 'status_anterior', NULL, 'status_novo', v_etiqueta.status, 'alertas', v_alertas, 'backfilled', true);
  END IF;
  v_status_anterior := v_etiqueta.status;
  IF v_etiqueta.status = 'descartada' THEN RETURN jsonb_build_object('ok', false, 'erro', 'Etiqueta descartada' || CASE WHEN v_etiqueta.replaced_by_uid IS NOT NULL THEN ' (substituida por ' || v_etiqueta.replaced_by_uid || ')' ELSE '' END, 'etiqueta', to_jsonb(v_etiqueta)); END IF;
  IF v_etiqueta.lote_validade_snapshot IS NOT NULL AND v_etiqueta.lote_validade_snapshot < CURRENT_DATE THEN v_alertas := v_alertas || jsonb_build_array(format('LOTE VENCIDO em %s', to_char(v_etiqueta.lote_validade_snapshot,'DD/MM/YYYY'))); END IF;
  IF p_etapa = 'separacao' THEN
    IF v_etiqueta.foi_separada THEN RETURN jsonb_build_object('ok', false, 'erro', format('Etiqueta %s ja esta com status "separada" — bip duplicado nesta etapa', p_uid), 'etiqueta', to_jsonb(v_etiqueta), 'status_anterior', v_status_anterior, 'status_novo', v_status_anterior); END IF;
    UPDATE public.etiquetas_qr SET foi_separada = TRUE, separada_at = NOW(), separada_por = v_user_id, loja_atual_id = COALESCE(v_loja_id, loja_atual_id) WHERE uid = p_uid RETURNING * INTO v_etiqueta;
    INSERT INTO public.etiquetas_qr_eventos (etiqueta_uid, tipo_evento, etapa, status_anterior, status_novo, loja_id, usuario_id, usuario_nome, referencia_tipo, referencia_id, metadata) VALUES (p_uid, 'bipada_separacao', 'separacao', v_status_anterior, v_status_anterior, v_loja_id, v_user_id, v_user_nome, v_referencia_tipo, v_referencia_id, p_contexto - 'payload');
    RETURN jsonb_build_object('ok', true, 'etiqueta', to_jsonb(v_etiqueta), 'status_anterior', v_status_anterior, 'status_novo', v_status_anterior, 'alertas', v_alertas, 'backfilled', false);
  END IF;
  IF p_etapa = 'conferencia' THEN
    IF v_etiqueta.foi_conferida THEN RETURN jsonb_build_object('ok', false, 'erro', format('Etiqueta %s ja esta com status "conferida" — bip duplicado nesta etapa', p_uid), 'etiqueta', to_jsonb(v_etiqueta), 'status_anterior', v_status_anterior, 'status_novo', v_status_anterior); END IF;
    UPDATE public.etiquetas_qr SET foi_conferida = TRUE, conferida_at = NOW(), conferida_por = v_user_id, loja_atual_id = COALESCE(v_loja_id, loja_atual_id) WHERE uid = p_uid RETURNING * INTO v_etiqueta;
    INSERT INTO public.etiquetas_qr_eventos (etiqueta_uid, tipo_evento, etapa, status_anterior, status_novo, loja_id, usuario_id, usuario_nome, referencia_tipo, referencia_id, metadata) VALUES (p_uid, 'bipada_conferencia', 'conferencia', v_status_anterior, v_status_anterior, v_loja_id, v_user_id, v_user_nome, v_referencia_tipo, v_referencia_id, p_contexto - 'payload');
    RETURN jsonb_build_object('ok', true, 'etiqueta', to_jsonb(v_etiqueta), 'status_anterior', v_status_anterior, 'status_novo', v_status_anterior, 'alertas', v_alertas, 'backfilled', false);
  END IF;
  v_status_novo := CASE p_etapa
    WHEN 'saida' THEN CASE WHEN v_etiqueta.status IN ('gerada','recebida','aberta','consumida') THEN 'em_transito' ELSE NULL END
    WHEN 'entrada' THEN CASE WHEN v_etiqueta.status IN ('em_transito','gerada','aberta','consumida') THEN 'recebida' WHEN v_etiqueta.status = 'recebida' AND v_loja_id IS DISTINCT FROM v_etiqueta.loja_atual_id THEN 'recebida' ELSE NULL END
    WHEN 'consumo' THEN 'consumida'
    WHEN 'descarte' THEN 'descartada'
  END;
  IF v_status_novo IS NULL THEN RETURN jsonb_build_object('ok', false, 'erro', format('Etiqueta %s ja esta com status "%s" — bip duplicado nesta etapa', p_uid, v_status_anterior), 'etiqueta', to_jsonb(v_etiqueta)); END IF;
  UPDATE public.etiquetas_qr SET status = v_status_novo, loja_atual_id = COALESCE(v_loja_id, loja_atual_id) WHERE uid = p_uid RETURNING * INTO v_etiqueta;
  INSERT INTO public.etiquetas_qr_eventos (etiqueta_uid, tipo_evento, etapa, status_anterior, status_novo, loja_id, usuario_id, usuario_nome, referencia_tipo, referencia_id, metadata) VALUES (p_uid, 'bipada_' || p_etapa, p_etapa, v_status_anterior, v_status_novo, v_loja_id, v_user_id, v_user_nome, v_referencia_tipo, v_referencia_id, p_contexto - 'payload');
  RETURN jsonb_build_object('ok', true, 'etiqueta', to_jsonb(v_etiqueta), 'status_anterior', v_status_anterior, 'status_novo', v_status_novo, 'alertas', v_alertas, 'backfilled', false);
END;
